# hypothesis: In a diamond hierarchy super() follows the C3 MRO, so Base.__init__ runs once and before the subclass bodies, and an override that narrows a parameter type is rejected.
from typing import reveal_type


class Base:
    def __init__(self, tag: str) -> None:
        self.trace: list[str] = [f'Base({tag})']

    def describe(self, verbose: object) -> str:
        return f'{len(self.trace)} steps'


class Left(Base):
    def __init__(self, tag: str) -> None:
        super().__init__(tag)
        self.trace.append('Left')


class Right(Base):
    def __init__(self, tag: str) -> None:
        super().__init__(tag)
        self.trace.append('Right')


class Diamond(Left, Right):
    def __init__(self, tag: str) -> None:
        super().__init__(tag)
        self.trace.append('Diamond')

    def describe(self, verbose: object) -> str:
        return 'diamond ' + super().describe(verbose)


class Narrow(Base):
    def describe(self, verbose: int) -> str:  # expect-error: parameter narrows object to int (LSP)
        return f'narrow {verbose}'


d = Diamond('x')
reveal_type(d.trace)
print(d.trace, [c.__name__ for c in Diamond.__mro__])
print(d.describe('v'), Narrow('y').describe(2))
